using System;using System.Data;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.IO;
namespace Videira {
partial class Store {
 public static void MaterialsSchema(DataSet d){if(!d.Tables.Contains("Embalagens insumos"))Table(d,"Embalagens insumos","Material","Unidade","Valor compra:n","Quantidade compra:n","Consumo por garrafa:n","Observações");Add(d.Tables["Empresa"],"Insumos importados",typeof(string),"Não");Add(d.Tables["Despesas"],"Insumo",typeof(int),0);}
 public bool SeedMaterials(){if(Company["Insumos importados"].ToString()=="Sim")return false;Data.Tables["Embalagens insumos"].Rows.Add(1,"SACOLA","UN",23m,74m,1m,"74 sacolas por R$ 23. Cabe até 2 garrafas; consumo padrão: 1 sacola por garrafa.");Data.Tables["Embalagens insumos"].Rows.Add(2,"FITA DUREX","CM",33.90m,50000m,15m,"5 rolos de 100 m (45 mm de largura). Total: 50.000 cm; consumo: 15 cm por garrafa.");Data.Tables["Embalagens insumos"].Rows.Add(3,"PLÁSTICO BOLHA","RECORTE",130m,855m,1m,"Rolo 1,10 x 100 m. Recortes 35 x 35 cm: 3 por faixa x 285 faixas = 855 recortes.");Company["Insumos importados"]="Sim";return true;}
 public decimal MaterialUnitCost(DataRow r){decimal q=(decimal)r["Quantidade compra"];if(q<=0)throw new Exception("Quantidade comprada deve ser maior que zero.");return (decimal)r["Valor compra"]/q;}
 public decimal MaterialsPerBottle{get{return Data.Tables["Embalagens insumos"].AsEnumerable().Sum(r=>MaterialUnitCost(r)*(decimal)r["Consumo por garrafa"]);}}
 public void MaterialPurchase(DataRow r,decimal value,decimal quantity,DateTime date){if(quantity<=0||value<0)throw new Exception("Confira quantidade e valor da compra.");Atomic(()=>{r["Valor compra"]=value;r["Quantidade compra"]=quantity;var expense=Data.Tables["Despesas"].NewRow();expense["Id"]=Next("Despesas");expense["Data"]=date.Date;expense["Categoria"]="Gastos variáveis";expense["Descrição"]="COMPRA EMBALAGEM: "+r["Material"]+" • "+quantity.ToString("N2")+" "+r["Unidade"];expense["Valor"]=value;expense["Insumo"]=r["Id"];Data.Tables["Despesas"].Rows.Add(expense);});}
}
partial class MainForm {
 void AddMaterialsTab(TabControl tabs){var tab=new TabPage("Despesas variáveis • Embalagens e insumos"){BackColor=Theme.Surface,Padding=new Padding(12)};tabs.TabPages.Add(tab);var l=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};l.RowStyles.Add(new RowStyle(SizeType.Absolute,100));l.RowStyles.Add(new RowStyle(SizeType.Percent,100));l.RowStyles.Add(new RowStyle(SizeType.Absolute,60));tab.Controls.Add(l);var info=new Label{Dock=DockStyle.Fill,ForeColor=Color.DimGray};l.Controls.Add(info,0,0);var g=Theme.Grid();g.Dock=DockStyle.Fill;l.Controls.Add(g,0,1);Action refresh=()=>{var t=db.Data.Tables["Embalagens insumos"].Copy();t.Columns.Add("Custo por medida R$",typeof(decimal));t.Columns.Add("Custo por garrafa R$",typeof(decimal));foreach(DataRow row in t.Rows){row["Custo por medida R$"]=db.MaterialUnitCost(row);row["Custo por garrafa R$"]=db.MaterialUnitCost(row)*(decimal)row["Consumo por garrafa"];}g.DataSource=t;g.Columns["Id"].Visible=false;g.Columns["Observações"].Visible=false;g.Columns["Material"].FillWeight=200;foreach(DataGridViewColumn c in g.Columns)if(c.ValueType==typeof(decimal))c.DefaultCellStyle.Format=c.Name.StartsWith("Custo")?"N4":"N2";info.Text="Custos variáveis: valor da compra ÷ quantidade comprada × consumo por garrafa.\nTotal dos materiais: R$ "+db.MaterialsPerBottle.ToString("N4")+" por garrafa. A precificação usa o campo Embalagem de cada produto (padrão R$ 1,00); os materiais não são somados novamente.\nEditar altera a referência de custo. Lançar compra registra o pagamento em Despesas e no financeiro. Compras não entram no rateio mensal do preço.";};Func<DataRow> selected=()=>{if(g.CurrentRow==null)throw new Exception("Selecione um material.");return db.Data.Tables["Embalagens insumos"].Rows.Find(g.CurrentRow.Cells["Id"].Value);};Action<DataRow> edit=row=>{using(var d=new Dialog("Embalagem / insumo • consumo por garrafa",850,650)){var name=d.TextField("Material",row==null?"":row["Material"].ToString());var unit=d.Choice("Unidade de medida",new[]{"UN","CM","M","RECORTE","ML","G"});unit.SelectedItem=row==null?"UN":row["Unidade"].ToString();var value=d.Number("Valor total da compra R$",row==null?0:(decimal)row["Valor compra"]);var quantity=d.Number("Quantidade total comprada",row==null?1:(decimal)row["Quantidade compra"],100000000,4);quantity.Minimum=0.0001m;var usage=d.Number("Consumo por garrafa",row==null?1:(decimal)row["Consumo por garrafa"],100000000,4);var note=d.TextField("Medidas / observações",row==null?"":row["Observações"].ToString());var calc=new Label{AutoSize=true};d.Add("Cálculo",calc);Action update=()=>calc.Text="R$ "+(value.Value/quantity.Value).ToString("N4")+" por "+unit.Text+" × "+usage.Value.ToString("N4")+" = R$ "+(value.Value/quantity.Value*usage.Value).ToString("N4")+" por garrafa";value.ValueChanged+=(s,e)=>update();quantity.ValueChanged+=(s,e)=>update();usage.ValueChanged+=(s,e)=>update();unit.SelectedIndexChanged+=(s,e)=>update();update();d.Commit(()=>{if(name.Text.Trim()=="")throw new Exception("Informe o material.");db.Atomic(()=>{if(row==null)db.Data.Tables["Embalagens insumos"].Rows.Add(db.Next("Embalagens insumos"),name.Text.Trim().ToUpperInvariant(),unit.Text,value.Value,quantity.Value,usage.Value,note.Text.Trim());else{row["Material"]=name.Text.Trim().ToUpperInvariant();row["Unidade"]=unit.Text;row["Valor compra"]=value.Value;row["Quantidade compra"]=quantity.Value;row["Consumo por garrafa"]=usage.Value;row["Observações"]=note.Text.Trim();}});});if(d.ShowDialog(this)==DialogResult.OK)refresh();}};
 var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};bar.Controls.Add(Btn("Novo insumo",()=>edit(null)));bar.Controls.Add(Btn("Editar consumo",()=>edit(selected())));bar.Controls.Add(Btn("Lançar compra",()=>{var row=selected();using(var d=new Dialog("Registrar compra de "+row["Material"],730,480)){var date=new DateTimePicker{Format=DateTimePickerFormat.Short,Value=DateTime.Today};d.Add("Data do pagamento",date);var value=d.Number("Valor pago R$",(decimal)row["Valor compra"]);var qty=d.Number("Quantidade comprada",(decimal)row["Quantidade compra"],100000000,4);qty.Minimum=.0001m;d.Add("No financeiro",new Label{Text="Registra saída de caixa. O resultado das vendas já considera o consumo da embalagem; a compra não será descontada novamente.",AutoSize=true,MaximumSize=new Size(500,100)});d.Commit(()=>db.MaterialPurchase(row,value.Value,qty.Value,date.Value));if(d.ShowDialog(this)==DialogResult.OK)refresh();}}));var apply=Btn("Usar custo calculado",()=>{decimal cost=Math.Ceiling(db.MaterialsPerBottle*100)/100;if(MessageBox.Show("Trocar a embalagem dos produtos pelo custo calculado de R$ "+cost.ToString("N2")+" por garrafa?\nSubstitui o valor atual; não soma ao R$ 1,00. O histórico de vendas permanece igual.","Aplicar custo da embalagem",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;db.Atomic(()=>{foreach(DataRow p in db.Data.Tables["Produtos"].Rows)p["Embalagem unitária"]=cost;});refresh();});apply.Width=195;bar.Controls.Add(apply);bar.Controls.Add(Btn("Sair",Home));l.Controls.Add(bar,0,2);g.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Run(()=>edit(selected()));};refresh();if(preview&&activePreviewMode=="--preview-materials")tabs.SelectedTab=tab;
 }
}
static class MaterialsTests {
 public static void Run(){var db=new Store(Path.Combine(Environment.CurrentDirectory,"work","Materials-"+Guid.NewGuid()));if(db.Data.Tables["Embalagens insumos"].Rows.Count!=3)throw new Exception("Insumos iniciais");var bag=db.Data.Tables["Embalagens insumos"].Rows.Find(1);if(db.MaterialUnitCost(bag)!=23m/74m)throw new Exception("Sacola 74 unidades");decimal total=23m/74m+33.90m/50000m*15m+130m/855m;if(Math.Abs(db.MaterialsPerBottle-total)>.0000001m)throw new Exception("Consumo por garrafa");bag["Consumo por garrafa"]=.5m;if(Math.Abs(db.MaterialsPerBottle-(total-23m/74m/2))>.0000001m)throw new Exception("Uso parcial");db.MaterialPurchase(bag,23,74,DateTime.Today);if(db.MonthlyPlan!=0||db.Data.Tables["Despesas"].Rows.Count!=1)throw new Exception("Compra fora do rateio");var finance=db.Finance(DateTime.Today,DateTime.Today);if((decimal)finance.Rows[7][1]!=0||(decimal)finance.Rows[9][1]!=23)throw new Exception("Compra e consumo sem dupla contagem");db.Save();db=new Store(db.Root);if(db.SeedMaterials()||db.Data.Tables["Embalagens insumos"].Rows.Count!=3||(decimal)db.Data.Tables["Embalagens insumos"].Rows.Find(1)["Consumo por garrafa"]!=.5m)throw new Exception("Insumos persistidos e sem duplicação");File.AppendAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"\r\nPASS 3.2: três materiais, sacolas 74, consumo por garrafa, uso parcial, compra variável fora do rateio, financeiro sem duplicação e persistência.");}
}
}
